# owner: platform
from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students given")
    for s in students:
        if not s.email:
            raise ProjectError(f"no email: {s.display_name}")


def _width(values: List[str]) -> int:
    return max(len(v) for v in values)


# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    ordered = sorted(students, key=lambda s: s.display_name)
    nw = _width([s.display_name for s in ordered])
    sw = _width([s.section for s in ordered])
    return [
        f"{s.display_name:<{nw}}  {s.section:<{sw}}  {s.email}"
        for s in ordered
    ]

