# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, section, email="a@x.org"):
    return Student("1", last, "Ann", section, email)


class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _student("Zed", "B", "z@x.org"),
            _student("Li", "A10", "l@x.org")
        ])
        self.assertEqual(rows[0], "Li, Ann   A10  l@x.org")
        self.assertEqual(rows[1], "Zed, Ann  B    z@x.org")

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([_student("Zed", "B", None)])
        self.assertIn("Zed, Ann", str(ctx.exception))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
